// SPDX-License-Identifier: MIT
pragma solidity ^0.8.28;

error InsufficientBalance();
error OnlyOwner();

contract GasHeavy {
    uint256 public totalSupply;
    mapping(address => uint256) public balances;
    address[] public holders;
    address public immutable owner;

    constructor() {
        owner = msg.sender;
    }

    function batchTransfer(address[] calldata to, uint256[] calldata amounts) external {
        uint256 len = to.length;
        uint256 senderBalance = balances[msg.sender];
        unchecked {
            for (uint256 i = 0; i < len; ++i) {
                uint256 amt = amounts[i];
                require(senderBalance >= amt, InsufficientBalance());
                senderBalance -= amt;
                address recipient = to[i];
                if (recipient != msg.sender) {
                    balances[recipient] += amt;
                }
            }
        }
        balances[msg.sender] = senderBalance;
    }

    function distributeRewards(uint256 rewardPerHolder) external {
        uint256 len = holders.length;
        unchecked {
            for (uint256 i = 0; i < len; ++i) {
                balances[holders[i]] += rewardPerHolder;
            }
        }
        totalSupply += rewardPerHolder * len;
    }

    function mint(address to, uint256 amount) external {
        if (msg.sender != owner) revert OnlyOwner();
        totalSupply += amount;
        balances[to] += amount;
        holders.push(to);
    }
}

